import {mountRegimeWatch} from './regime.js';
const paths={grid:'<rect x="3" y="3" width="7" height="7" rx="1.5"/><rect x="14" y="3" width="7" height="7" rx="1.5"/><rect x="3" y="14" width="7" height="7" rx="1.5"/><rect x="14" y="14" width="7" height="7" rx="1.5"/>',activity:'<path d="M3 12h4l3-8 4 16 3-8h4"/>',chart:'<path d="M4 3v17h17M8 15l4-5 4 2 5-7"/>',book:'<path d="M3 5c3-1 6-1 9 1 3-2 6-2 9-1v15c-3-1-6-1-9 1-3-2-6-2-9-1zM12 6v15"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="2"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6M12 7h.01"/>',calendar:'<rect x="3" y="5" width="18" height="16" rx="2"/><path d="M7 3v4M17 3v4M3 10h18M7 14h3M14 14h3M7 17h3"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 15v5h16v-5"/>',check:'<path d="m5 12 4 4L19 6"/>',chevron:'<path d="m6 9 6 6 6-6"/>',table:'<rect x="3" y="4" width="18" height="16" rx="2"/><path d="M3 10h18M9 4v16M3 15h18"/>',spark:'<path d="m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5z"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',tc:'<path d="M4 19V8l5 3V5l6 5 5-3v12zM8 15h1M12 15h1M16 15h1"/>',acid:'<path d="M9 3h6M10 3v6l-6 10a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 15h10M10 18h.01M14 17h.01"/>',production:'<path d="m12 3 9 5v9l-9 5-9-5V8zM3 8l9 5 9-5M12 13v9M7.5 5.5l9 5"/>',imports:'<path d="M4 12h16l-2 7H7zM8 12V6h8v6M12 3v6m-3-3 3 3 3-3M3 21c2-2 4 2 6 0s4 2 6 0 4 2 6 0"/>',inventory:'<path d="m3 8 9-5 9 5v13H3zM7 21V11h10v10M7 15h10M7 18h10"/>',premium:'<circle cx="12" cy="12" r="9"/><path d="M15 8h-4a2 2 0 0 0 0 4h2a2 2 0 0 1 0 4H9M12 6v12"/>'};
const icon=(name)=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.info}</svg>`;
const $=s=>document.querySelector(s);const $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const niceDate=(s)=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'});
const shortDate=(s)=>new Date(s+'T12:00:00Z').toLocaleDateString('en-GB',{day:'numeric',month:'short',timeZone:'UTC'});
const fmt=(v,n=0)=>new Intl.NumberFormat('en-US',{minimumFractionDigits:n,maximumFractionDigits:n}).format(v).replace('-','−');
function mountIcons(root=document){root.querySelectorAll('[data-icon]').forEach(el=>el.innerHTML=icon(el.dataset.icon));}
mountIcons();
let DATA,selected='premium',premiumView='weekly',productionSource='SMM',previousFocus,toastTimeout;
const dialog=$('#detail-dialog');
function openDialog(html){previousFocus=document.activeElement;$('#dialog-content').innerHTML=html;dialog.showModal();dialog.scrollTop=0;$('#close-dialog').focus();}
function closeDialog(){dialog.close();previousFocus?.focus();}
$('#close-dialog').addEventListener('click',closeDialog);dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
dialog.addEventListener('close',()=>previousFocus?.focus());
function metric(id){return DATA.metrics.find(m=>m.id===id);}
function sourceList(ids){return ids.map(id=>{const s=DATA.sources[id];return `<div class="source-item"><a href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.label)}</a><div class="source-meta">${esc(s.type)}${s.published?' · Published '+esc(s.published):''}</div><p>${esc(s.note)}</p></div>`;}).join('');}
function valueText(m,source=productionSource){if(m.id==='tc')return '$'+fmt(m.value,2);if(m.id==='acid')return '¥'+fmt(m.value,1);if(m.id==='premium')return '$'+fmt(m.value);if(m.id==='production')return fmt(source==='SMM'?m.value:1.222,4);if(m.id==='imports')return fmt(m.value,4);return fmt(m.value);}
function showMetric(id){const m=metric(id);openDialog(`<h2 class="dialog-title">${esc(m.name)}</h2><div class="detail-value">${esc(valueText(m))}<span>${esc(m.unit)}</span></div><p class="detail-meta">${esc(m.period)} · ${esc(m.status)}${m.id==='production'?' · '+productionSource:''}</p><p class="dialog-lead">${esc(m.meaning)}</p><div class="detail-block"><h3>Reporting basis</h3><p>${esc(m.method)}</p></div><div class="detail-block"><h3>Read the number correctly</h3><p>${esc(m.detail)}</p></div><div class="detail-block"><h3>Sources & provenance</h3>${sourceList(m.sourceIds)}</div>`);}
function showCoverage(){openDialog(`<h2 class="dialog-title">A clear view of data coverage.</h2><p class="dialog-lead">Verified on 25 November 2026. This is a curated research snapshot, with each observation's own date. It does not refresh automatically.</p><div style="overflow-x:auto"><table class="coverage-table"><thead><tr><th>Indicator</th><th>Observation</th><th>Coverage</th></tr></thead><tbody>${DATA.metrics.map(m=>`<tr><td>${esc(m.short)}</td><td>${esc(m.period)}</td><td>${esc(m.status)}</td></tr>`).join('')}</tbody></table></div><div class="detail-block"><h3>Older assessments remain visible</h3><p>TC/RC and sulphuric acid use November 6 observations. More recent licensed values were not retrieved. They are not presented as today's quotes.</p></div><div class="detail-block"><h3>Different sources stay separate</h3><p>SMM and NBS production are separate datasets. Argus TC and the comparison Platts assessment use different methodologies. Premium charts separate daily warrant prices from published weekly averages. SHFE warehouse stocks are separate from registered warrants and social inventories.</p></div><div class="detail-block"><h3>Charts & calculations</h3><p>Only sourced observations are plotted. Lines connect observations and do not represent daily estimates. RC is calculated as 10% of the numerical Argus TC and shown in US cents per pound. Prior-week SHFE stock is derived from the published current stock and weekly change.</p></div><div class="detail-block"><h3>Automatic updates</h3><p>No subscription or live data feed is connected. Automatic refresh would require authorized provider feeds and a scheduled ingestion process. Original quoted currencies are preserved.</p></div>`);}
function showSources(){openDialog(`<h2 class="dialog-title">The source register.</h2><p class="dialog-lead">Public reports checked on 25 November 2026. Direct assessments, reported official statistics and calculated values are identified separately.</p>${sourceList(Object.keys(DATA.sources))}`);}
function renderCards(){const chips={tc:'ARGUS',acid:'SMM',production:productionSource,imports:'CHINA CUSTOMS',inventory:'SHFE',premium:'SMM'};$('#metric-grid').innerHTML=DATA.metrics.map((m,i)=>{let num=valueText(m);const prefix=/^[$¥]/.test(num)?num[0]:'';if(prefix)num=num.slice(1);let units={tc:'/dmt',acid:'/t',production:'Mt',imports:'Mt',inventory:'t',premium:'/t'}[m.id];let delta=m.id==='production'&&productionSource==='NBS'?'+1.80% YoY · NBS':m.delta;let extra=m.id==='tc'?'<span class="rc-label">RC −24.72¢/lb · calc.</span>':m.id==='production'?`<div class="production-toggle" role="group" aria-label="Production data source"><button data-production="SMM" class="${productionSource==='SMM'?'selected':''}" aria-pressed="${productionSource==='SMM'}">SMM</button><button data-production="NBS" class="${productionSource==='NBS'?'selected':''}" aria-pressed="${productionSource==='NBS'}">NBS</button></div>`:'';return `<article class="metric-card" style="--i:${i}" data-card="${m.id}"><div class="card-top"><div class="card-title-wrap"><span class="card-symbol">${icon(m.id)}</span><button class="card-title card-open" data-detail="${m.id}">${esc(m.short)}</button></div><button class="card-info" data-detail="${m.id}" aria-label="Source and details for ${esc(m.short)}">${icon('info')}</button></div><div class="card-value">${prefix?`<span class="currency">${prefix}</span>`:''}${num}<span class="value-unit">${units}</span></div><div class="card-subline"><span class="delta ${m.deltaType==='up'||m.id==='production'&&productionSource==='NBS'?'up':''}">${esc(delta)}</span>${extra}</div><div class="card-footer"><span class="source-chip">${chips[m.id]}</span><span class="${m.status==='Older public quote'?'stale-chip':''}">${esc(m.period)}${m.status==='Older public quote'?' · older quote':''}</span></div></article>`;}).join('');
$$('[data-detail]').forEach(b=>b.addEventListener('click',()=>showMetric(b.dataset.detail)));
$$('[data-card]').forEach(card=>card.addEventListener('click',e=>{if(!e.target.closest('button'))showMetric(card.dataset.card);}));
$$('[data-production]').forEach(b=>b.addEventListener('click',()=>{productionSource=b.dataset.production;renderCards();if(selected==='production')renderChart();}));}
function chartData(){const m=metric(selected);return selected==='premium'&&premiumView==='weekly'?m.weekly:m.series;}
function renderChart(){const m=metric(selected),points=chartData(),weekly=selected==='premium'&&premiumView==='weekly';$('#chart-view').hidden=selected!=='premium';$$('[data-view]').forEach(b=>{b.classList.toggle('selected',b.dataset.view===premiumView);b.setAttribute('aria-pressed',String(b.dataset.view===premiumView));});
const last=points.at(-1);const unit=selected==='production'||selected==='imports'?'million tonnes':selected==='tc'?'USD / dry tonne':selected==='acid'?'CNY / tonne':selected==='inventory'?'tonnes':'USD / tonne';
$('#chart-value').textContent=selected==='production'?'1.0867 / 1.2220':(selected==='premium'||selected==='tc'?'$':selected==='acid'?'¥':'')+fmt(last.value,['production','imports'].includes(selected)?4:selected==='tc'?2:selected==='acid'?1:0);
$('#chart-unit').textContent=' '+unit;
$('#chart-context').textContent=weekly?'Published 19 Nov · warrant weekly average':selected==='production'?'October 2026 · SMM / NBS, separate datasets':selected==='imports'?'October 2026 · gross ore & concentrate mass':shortDate(last.date)+' 2026 · '+m.frequency.toLowerCase()+' observation';
$('#chart-footnote').textContent=weekly?'Publication dates · last review is week to date.':selected==='production'?'Separate methodologies. These bars are not a time series.':points.length===1?'One sourced monthly observation; no historical trend inferred.':selected==='inventory'?'13 Nov derived from reported stock and weekly change.':'Published observations only. Lines connect observations.';
const W=720,H=257,L=53,R=30,T=29,B=35,innerW=W-L-R,innerH=H-T-B;
const categorical=['production','imports'].includes(selected);let ymin=selected==='tc'?-280:0;let ymax=selected==='tc'?0:selected==='premium'?450:selected==='acid'?1600:selected==='inventory'?40000:selected==='production'?1.4:2.5;
const y=v=>T+innerH*(1-(v-ymin)/(ymax-ymin));const times=points.map(p=>Date.parse(p.date));let tmin=Math.min(...times),tmax=Math.max(...times);const x=(p,i)=>categorical?L+innerW*(i+.5)/points.length:L+18+(innerW-36)*((Date.parse(p.date)-tmin)/(tmax-tmin||1));
let svg=`<svg class="market-chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(m.name)}: ${weekly?'published weekly averages':categorical?'monthly observations':'sourced observations'}"><defs><linearGradient id="chart-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#d6a579" stop-opacity=".20"/><stop offset="100%" stop-color="#d6a579" stop-opacity="0"/></linearGradient><linearGradient id="bar-fill" x1="0" x2="0" y1="0" y2="1"><stop offset="0%" stop-color="#ddb78f" stop-opacity=".85"/><stop offset="100%" stop-color="#9e7651" stop-opacity=".14"/></linearGradient></defs>`;
for(let i=0;i<=4;i++){const val=ymin+(ymax-ymin)*i/4,Y=y(val);const label=selected==='inventory'?fmt(val/1000)+'k':['production','imports'].includes(selected)?fmt(val,2):fmt(val);svg+=`<line x1="${L}" x2="${W-R}" y1="${Y}" y2="${Y}" class="chart-grid"/><text x="${L-12}" y="${Y+4}" text-anchor="end" class="chart-y-label">${label}</text>`;}
if(!categorical&&points.length>1){const coords=points.map((p,i)=>`${x(p,i)},${y(p.value)}`);const baseline=selected==='tc'?y(0):y(ymin);svg+=`<path d="M${x(points[0],0)},${baseline} L${coords.join(' L')} L${x(last,points.length-1)},${baseline} Z" fill="url(#chart-fill)"/><path d="M${coords.join(' L')}" class="chart-line"/>`;}
points.forEach((p,i)=>{const X=x(p,i),Y=y(p.value),showX=categorical||points.length<5||i===0||i===points.length-1||i===2;const chartN=fmt(p.value,['production','imports'].includes(selected)?4:selected==='tc'?2:selected==='acid'?1:0);if(categorical){const bw=Math.min(112,innerW/points.length*.40),base=y(0);svg+=`<rect x="${X-bw/2}" y="${Y}" width="${bw}" height="${base-Y}" rx="6" fill="url(#bar-fill)" stroke="#d2aa7d66"/><text x="${X}" y="${Y-12}" text-anchor="middle" class="chart-data-label">${chartN}</text>`;}else{svg+=`<g class="point-hit" tabindex="0" role="button" aria-label="${esc(niceDate(p.date))}: ${chartN} ${esc(unit)}" data-point="${i}"><title>${esc(niceDate(p.date))}: ${chartN} ${esc(unit)}</title><circle cx="${X}" cy="${Y}" r="18" fill="transparent"/><circle class="point-visual" cx="${X}" cy="${Y}" r="4.5" fill="#d8b68e" stroke="#202c2f" stroke-width="2"/></g>`;if(points.length<=4)svg+=`<text x="${X}" y="${Y-14}" text-anchor="middle" class="chart-data-label">${chartN}</text>`;}
if(showX)svg+=`<text x="${X}" y="${H-11}" text-anchor="middle" class="chart-x-label">${esc(p.label||shortDate(p.date))}</text>`;});
svg+='</svg><div class="chart-tooltip" hidden></div>';$('#chart-container').innerHTML=svg;
const tooltip=$('.chart-tooltip');$$('[data-point]').forEach(el=>{const index=Number(el.dataset.point),p=points[index];const show=()=>{tooltip.hidden=false;tooltip.innerHTML=`${esc(fmt(p.value,selected==='tc'?2:selected==='acid'?1:0))} ${esc(unit)}<span>${esc(p.period||niceDate(p.date))}${p.derived?' · derived':''}</span>`;const parent=$('#chart-container'),actual=parent.getBoundingClientRect();tooltip.style.left=(x(p,index)/W*actual.width)+'px';tooltip.style.top=(y(p.value)/H*actual.height-15)+'px';};el.addEventListener('mouseenter',show);el.addEventListener('focus',show);el.addEventListener('mouseleave',()=>tooltip.hidden=true);el.addEventListener('blur',()=>tooltip.hidden=true);el.addEventListener('click',()=>showMetric(selected));el.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();showMetric(selected);}});});
$('#chart-table').innerHTML=`<table><caption class="sr-only">Sourced observations in the selected chart</caption><thead><tr><th>${categorical?'Series':'Observation'}</th><th>Value (${esc(unit)})</th><th>Source</th></tr></thead><tbody>${points.map(p=>`<tr><td>${esc(p.label||p.period||niceDate(p.date))}${p.derived?' · derived':''}</td><td>${fmt(p.value,['production','imports'].includes(selected)?4:selected==='tc'?2:selected==='acid'?1:0)}</td><td><a href="${esc(DATA.sources[p.source].url)}" target="_blank" rel="noopener noreferrer">${esc(DATA.sources[p.source].publisher)}</a></td></tr>`).join('')}</tbody></table>`;
const insight=selected==='premium'?{heading:'A window into physical demand.',text:'Yangshan warrant premiums averaged $340/t on 25 November, down $50/t day on day. The weekly chart provides context; it uses separate published averages.',basis:'SMM · registered-copper warrants'}:{heading:m.summary,text:m.meaning,basis:m.period+' · '+m.status};
$('#insight-content').innerHTML=`<h3 id="insight-title">${esc(insight.heading)}</h3><p>${esc(insight.text)}</p><div class="insight-basis">${icon('book')} ${esc(insight.basis)}</div>`;
}
function exportCSV(){const rows=[['Indicator','Series','Period','Observation date','Value','Unit','Value type','Source URL','Verified date']];DATA.metrics.forEach(m=>{const add=(points,series)=>points.forEach(p=>rows.push([m.name,p.label||series,p.period||m.period,p.date,p.value,m.unit,p.derived?'Calculated from reported change':'Reported observation',DATA.sources[p.source].url,DATA.asOf]));add(m.series,m.id==='premium'?'Daily warrants':m.id==='tc'?'Argus spot TC':m.id==='acid'?'SMM copper-smelting acid index':'');if(m.weekly)add(m.weekly,'Published weekly warrant average');});rows.push(['Spot concentrate RC','Argus convention','6 Nov 2026','2026-11-06',-24.72,'US cents/lb','Calculated: −247.20 × 0.1',DATA.sources.argusMethod.url,DATA.asOf]);rows.push(['Concentrate imports','GACC YTD','Jan–Oct 2026','2026-10-31',24.1421,'million t','Reported preliminary statistic',DATA.sources.customs.url,DATA.asOf]);rows.push(['Concentrate imports','GACC YTD YoY','Jan–Oct 2026','2026-10-31',-3.8,'percent','Reported YTD change',DATA.sources.customs.url,DATA.asOf]);const cases=DATA.regime?.cases;if(cases){const a=cases.acidSeller,b=cases.acidBuyer;rows.push(['Regime watch','Kamoa-Kakula acid credit',a.period,'2026-09-30',a.credit,a.unit,'Reported cash-cost component',DATA.sources[a.source].url,DATA.asOf]);rows.push(['Regime watch','Kamoa-Kakula smelter operating cost',a.period,'2026-09-30',a.cost,a.unit,'Reported cash-cost component',DATA.sources[a.source].url,DATA.asOf]);rows.push(['Regime watch','Mantos Blancos acid price','Q3 2026','2026-09-30',b.current,b.unit,'Reported company operating input',DATA.sources[b.source].url,DATA.asOf]);rows.push(['Regime watch','Mantos Blancos acid price','Q3 2025','2025-09-30',b.previous,b.unit,'Reported company operating input',DATA.sources[b.source].url,DATA.asOf]);rows.push(['Regime watch','Annual benchmark TC','2026','2026',0,'USD/t','Annual contract benchmark; not spot TC',DATA.sources.regimeIEA.url,DATA.asOf]);}const csv='\uFEFF'+rows.map(row=>row.map(c=>'"'+String(c).replace(/"/g,'""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8;'}));const a=document.createElement('a');a.href=url;a.download='copper-observatory-2026-11-25.csv';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Sourced observations exported as CSV.');}
function toast(message){clearTimeout(toastTimeout);$('#toast').textContent=message;$('#toast').classList.add('visible');toastTimeout=setTimeout(()=>$('#toast').classList.remove('visible'),3500);}
async function init(){try{const response=await fetch('./data.json');if(!response.ok)throw new Error('Data request failed');DATA=await response.json();renderCards();renderChart();mountRegimeWatch({data:DATA,openDialog,sourceList,esc,fmt,icon,selectMetric:(id)=>{selected=id;$('#metric-select').value=id;renderChart();$('#explorer').scrollIntoView({behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'});$('#metric-select').focus({preventScroll:true});}});$('#metric-select').addEventListener('change',e=>{selected=e.target.value;renderChart();});$$('[data-view]').forEach(b=>b.addEventListener('click',()=>{premiumView=b.dataset.view;renderChart();}));$('#table-toggle').addEventListener('click',()=>{const table=$('#chart-table');table.hidden=!table.hidden;$('#table-toggle').setAttribute('aria-expanded',String(!table.hidden));$('#table-toggle').innerHTML=icon('table')+(table.hidden?'View data':'Hide data');});$('#chart-info').addEventListener('click',()=>showMetric(selected));$('#insight-source').addEventListener('click',()=>showMetric(selected));['#coverage-button','#methodology-button','#footer-method'].forEach(s=>$(s).addEventListener('click',showCoverage));$('#all-sources').addEventListener('click',showSources);$$('[data-source-metric]').forEach(b=>b.addEventListener('click',()=>showMetric(b.dataset.sourceMetric)));$('#export-button').addEventListener('click',exportCSV);const navObserver=new IntersectionObserver(entries=>{entries.forEach(entry=>{if(entry.isIntersecting){$$('[data-nav]').forEach(n=>{const active=n.dataset.nav===entry.target.id;n.classList.toggle('active',active);active?n.setAttribute('aria-current','location'):n.removeAttribute('aria-current');});}});},{rootMargin:'-5% 0px -65% 0px',threshold:0});['overview','indicators','regime-watch','explorer','sources'].forEach(id=>navObserver.observe(document.getElementById(id)));}catch(e){$('#metric-grid').innerHTML='<p class="loading">The research snapshot could not be loaded. Please reload the page.</p>';$('#chart-container').textContent='Data unavailable.';console.error('Could not load copper research snapshot',e);}}
init();
